const body = $input.first().json;
const eventType = body.type ?? body.eventType ?? '';
const payment = body.data?.object ?? body.data ?? body;
const metadata = payment.metadata ?? {};
const opportunityId =
  metadata.opportunityId ?? metadata.opportunity_id ?? metadata.dealId ?? '';
const amountCents = Number(payment.amount ?? 0);
const currency = String(payment.currency ?? '').toUpperCase();
const amountLabel =
  amountCents > 0
    ? `${(amountCents / 100).toFixed(2)} ${currency}`.trim()
    : '';
const isSucceeded =
  eventType === 'payment_intent.succeeded' ||
  eventType === 'checkout.session.completed' ||
  Boolean(opportunityId && payment.id);
const wonStage = $env.TWENTY_WON_STAGE || 'WON';

const teamsPayload = {
  type: 'message',
  attachments: [
    {
      contentType: 'application/vnd.microsoft.card.adaptive',
      content: {
        $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
        type: 'AdaptiveCard',
        version: '1.4',
        body: [
          {
            type: 'TextBlock',
            text: '🎉 Deal Won',
            weight: 'Bolder',
            size: 'Medium',
            color: 'Good',
          },
          {
            type: 'FactSet',
            facts: [
              { title: 'Deal', value: String(opportunityId || 'unknown') },
              { title: 'Value', value: String(amountLabel) },
              { title: 'Stripe', value: String(payment.id ?? '') },
            ],
          },
        ],
      },
    },
  ],
};

return [
  {
    json: {
      isSucceeded,
      opportunityId,
      amountLabel,
      stripePaymentId: payment.id ?? null,
      teamsPayload,
      graphqlBody: {
        query:
          'mutation UpdateOpportunityWon($id: UUID!, $data: OpportunityUpdateInput!) { updateOpportunity(id: $id, data: $data) { id stage } }',
        variables: {
          id: opportunityId,
          data: { stage: wonStage },
        },
      },
    },
  },
];
